test('pro plan checkout completes', async ({ page }) => {
  await test.step('Open login', () => page.goto('https://app.acme.dev/login'));
  await test.step('Sign in', async () => {
    await page.getByLabel('Email').fill(process.env.CHECKOUT_EMAIL!);
    await page.getByLabel('Password').fill(process.env.CHECKOUT_PASSWORD!);
    await page.getByRole('button', { name: 'Sign in' }).click();
  });
  await test.step('Open pricing', () => page.goto('https://app.acme.dev/pricing'));
  await test.step('Start Pro', () => page.getByRole('button', { name: 'Start Pro' }).click());

  const card = page.frameLocator('iframe[name^="__privateStripeFrame"]').first();
  await test.step('Enter card', () => card.getByPlaceholder('Card number').fill('4242 4242 4242 4242'));
  await test.step('Enter expiry and CVC', async () => {
    await card.getByPlaceholder('MM / YY').fill('12 / 34');
    await card.getByPlaceholder('CVC').fill('123');
  });
  await test.step('Pay $29', () => page.getByRole('button', { name: /Pay \$29/ }).click());
  await test.step('Payment confirmed', () =>
    expect(page.getByRole('heading', { name: 'Payment confirmed' })).toBeVisible({ timeout: 15_000 })
  );
}); checkout-monitor.zip
